        "평가사유": "[화제성 7점] 확정 사실 → 시즌4까지 이어진 드라마 '신병'의 첫 극장판이다. 드라마를 연출한 민진기 감독이 메가폰을 잡고 김민호·남태우·김요한이 다시 출연한다. 류경수, 트와이스 정연(간호장교 역)이 새로 합류했다(마이데일리·인사이트·TV리포트, 2026년 10월).\n추정 → 정연의 캐스팅으로 아이돌 팬층의 언급량은 늘겠지만, 원작 팬덤 규모는 드라마 시청층에 한정돼 8점까지는 주지 않았다.\n[독창성 6점] 확정 사실 → 군대 코미디 IP를 공포 코미디로 바꿨고, 드라마 시즌 사이의 이야기를 극장판으로 풀었다. 스튜디오지니가 드라마 IP를 영화로 옮기는 첫 사례로 보도됐다.\n군대·병원 괴담 소재 자체는 흔하다.\n[근접성 9점] 확정 사실 → 한국 제작에 국내 극장 개봉이다. 한국 남성 다수가 겪는 군 생활을 소재로 해 정서적 거리가 매우 가깝다.\n[영향성 5점] 추정 → 연말 성수기 경쟁작 사이에서 팬층 중심 흥행이 예상된다. 드라마 IP 극장판은 흥행 편차가 커 대형 흥행을 단정할 근거가 없다.\n파급력도 원작 팬층과 2030 남성층에 머물 가능성이 높다.\n[종합] 강점: 검증된 국내 드라마 IP, 군대 공감대, 정연 캐스팅. 약점: 개봉일 12/30은 KOBIS 등록과 배급사 공식 발표(2026-10-29)로 확정됐고, 연말 텐트폴(어벤져스·듄) 이후 스크린 확보가 관건이다. 편성 관점: 연말·연초 국내 코미디 꼭지 후보.\n[11-08 확인] KOBIS 개봉(예정)일 2026-12-30(최종수정 2026-11-01) 등록 확인 — 직전 '공란' 리스크 해소.",
