        "개요": "하이브·게펜레코드가 함께 만든 글로벌 걸그룹 캣츠아이가 데뷔 후 처음 여는 한국 단독 공연이다. 2027-01-27 요코하마에서 출발해 03-05 오클랜드까지 아시아·오세아니아 11개 도시를 도는 '와일드월드 투어'의 서울 공연으로, 약 1만 5천 석 규모의 KSPO DOME에서 한 번만 열린다. 한국인 멤버 윤채가 고국 팬을 처음 만나는 무대다. 북미 공연 중 멤버 메간이 뇌진탕으로 11-03 디트로이트, 11-05 시카고, 11-07 미니애폴리스 공연이 연기됐으나 11-09 오스틴 공연부터 동작을 줄인 채 복귀했다. 서울 공연 일정 변경 공지는 없다. 마농은 2026년 2월부터 활동을 쉬고 있어 복귀 시점이 미정이고, 소피아는 2027년 1월 첫째 주 복귀 예정이라 서울 무대의 출연 멤버 구성은 아직 확정되지 않았다.",
