        "평가사유": "[화제성 7점] (확정 →) KOPIS에 서울 올림픽공원 11-27~29 3일(PF301499)과 부산 12-12~13·대구 12-19·대전 12-26 회차가 모두 등록돼 있다. '가왕' 조용필은 전 세대에 걸친 대중 인지도를 가진 사실상 유일한 국내 아티스트군에 속한다. (추정 →) 예매 지표는 미확인이나 직전 투어들이 조기 매진된 전례가 있다.\n[독창성 3점] (독점성·희소성·차별 기획 관점) 전국투어 반복 포맷이고 독점 취재권이 없다. 공연 실황은 SNS·공중파가 실시간으로 다루는 영역이라 차별 확보가 어렵다(캘리브레이션 원칙 1·2).\n[근접성 8점] (수도권/지방·기간·관객 친숙도) 서울 3일 + 부산·대구·대전으로 윈도우 전 구간에 걸치고, 수도권 대형 공연장 편성이 있다. 한국 관객 친숙도는 최상위.\n[영향성 7점] (10-13 상향 6→7) KOPIS 재조회 결과 서울 공연장이 KSPO DOME(체조경기장)으로 확인돼, 3일 아레나 + 부산 벡스코·대구 엑스코·대전 DCC 전시장급 순회로 관람 규모가 직전 판단보다 크다. 세대 통합형 소재라 팬덤 한정 콘서트보다 파급이 넓지만, 공연 자체가 문화 의제로 확장되기에는 제한이 있다.\n[종합] 강점: 전 세대 인지도, 수도권 3일 + 전국 순회로 편성 유연성 높음. 약점·리스크: 독점 확보 불가, 반복 투어라 신선도 낮음. 직전 회차가 놓친 건이라 경쟁 매체도 동시에 포착할 수 있다. 편성 관점: 11-27 서울 개막에 맞춰 '가왕의 연말 투어' 프레임으로 붙이고, 12월 지방 회차를 재노출 창구로 쓴다. (10-13 보강) 서울 회차는 KSPO DOME 3일, 지방은 전시장 대형 홀이다. 동원 규모가 커져 영향성을 한 단계 올린다. 매진 여부는 미확인이다.",
