        "시작일": "2026-12-31",
        "이벤트명": "2026 제야의 종 타종행사(보신각)",
        "평점": 8.25,
        "개요": "33번의 타종과 보신각 지붕 미디어 매핑·카운트다운으로 새해를 여는 국가 대표 송년 행사. 종로 일대 차량 통제와 대중교통 연장운행이 뒤따르는 초대형 도심 군집 행사.",
        "영향성": 8,
        "평가사유": "[화제성 9점] (일정 확정 / 규모는 과거 실적 →) 대한민국 대표 송년 행사로 매년 전국 생중계되고 보신각 일대에 수만 명이 모인다(직전 회차 종로 차량 통제·지하철 버스 새벽 2시 연장운행). 펀서울이 2026-12-31~2027-01-01 회차를 '(예정)' 없이 게시해 개최가 확정됐다. 서울윈터페스티벌 세부축제로 묶였지만, 타종 자체가 독립된 전국구 의례라 상위 축제와 별개로 화제성을 유지한다.\n[독창성 6점] (중계·희소성) 33번 타종·미디어 매핑·카운트다운 구성이 매년 같고 전 방송사가 동시 중계한다. 시민 대표 타종 인사 선정이 유일한 변별 후크다.\n[근접성 10점] 서울 도심 + 무료 + 대중교통 연장운행.\n[영향성 8점] 새해 첫 장면으로 전국 동시 주목, 즉시성·확산성 최상급.\n[종합] 강점: 확보 난도가 낮은 전국구 송년 소재, 이번 회차 일정 확정 / 약점·리스크: 매년 같은 그림이라 차별화가 어렵고, 인파 밀집 안전관리·한파가 곧 사건 리스크. 시간·타종 인사는 12월 하순 발표 / 편성 코멘트: 연말 생중계 고정 꼭지, 타종 인사 스토리로 차별화하되 서울라이트 DDP·서울콘 카운트다운과 같은 시각이라 거점 1곳 집중.",
        "기간": "2026-12-31 ~ 2027-01-01 (시간 미공고; 직전 회차 22:50 ~ 00:20)",
