        "개요": "2023년 출범한 세계 최대 인플루언서 박람회형 K-컬처 축제. 직전 2025 회차는 서울콘 APAN Star Awards(2025-12-29 DDP 아트홀1관)·K-뷰티·스트리트 댄스 등으로 연말 동대문 일대를 채우고 새해 카운트다운으로 마무리했다. 2026 APAN Star Awards 개최일은 미발표.",
        "영향성": 8,
        "평가사유": "[화제성 8점] (일정 잠정 — 펀서울 목록 12/29~1/1 게시, SBA 공식 일정 발표 전 / 동원은 직전 회차 실적 →) 직전 2025 회차가 관람객 9만 4,460명(전년 대비 +53.4%), 56개국 인플루언서 3,567팀 참여, 콘텐츠 누적 4억 5,055만 뷰, 경제효과 1,757억 원을 기록했다. 국내 동원 자체는 10만 명 미만이지만 글로벌 온라인 확산력이 압도적이라 화제성 상위권으로 본다.\n[독창성 7점] (희소성/제휴) 인플루언서 수천 팀을 한자리에 모으는 포맷은 국내에 대체재가 없고 서울시·SBA 주최라 제휴·협찬 진입 여지도 있다. 다만 2025 회차의 중계 후크였던 APAN Star Awards는 2026년엔 서울콘과 분리돼 12/23 상명아트센터 계당홀(tvN 생중계)에서 따로 열린다(한국연예매니지먼트협회 10/30 발표) — 서울콘 자체의 중계형 후크가 빠져 1점 낮춘다.\n[근접성 9점] DDP 일원 + 대부분 무료 + 지하철 직결. 접근성 최상위권.\n[영향성 8점] K-컬처 수출·외래관광객 유치 의제로 매년 전국 뉴스에 노출되고, 새해 카운트다운으로 마무리돼 연말 의제를 선점한다.\n[종합] 강점: 12월 말 DDP 개최(SBA·누리하우스 업무협약) + 검증된 글로벌 확산 실적 + 수도권 무료. 창 안 K-컬처 이벤트 중 확보 가치 1순위. 약점·리스크: 국내 현장 동원은 10만 명 미만이라 '대형 군집'의 체감 규모는 기대보다 작을 수 있고, 12/29~1/1은 취재 인력이 가장 부족한 구간이다. 같은 기간 서울라이트 DDP 겨울이 같은 DDP에서 열려 그림이 겹친다. 편성: 개막(12/29) 현장 스케치와 12/31~1/1 카운트다운으로 나눠 2회(APAN은 12/23 별도 행사라 이 꼭지에서 제외).",
