        "평가사유": "[화제성 9점] 확정 → 2026년 23일간 잠정 159만 명(외국인 약 11.4만 명), 2025년 186만 명 방문(폐막 보도). 매년 백만 명대를 동원하는 국가대표급 겨울 명물. 2027년 일정 1/9~31은 (재)나라의 공식 협찬기업 모집 공고와 관광공사 DB에 명시됐다. 추정 → 2027 동원은 결빙·한파 변수에 좌우.\n[독창성 7점] 얼음판 위 수만 명 낚시 장면 자체가 압도적 영상 소재. 이용료 인상·환급 확대, 야간 레이저·드론 등 신규 콘텐츠가 검토 중(100여 건 제안, 도입 미확정)이라 새 그림 가능성. 다만 매년 전 방송사가 개막 스케치를 다루는 연례 행사라 독점성은 제한적.\n[근접성 6점] 수도권에서 2시간 안팎이나 강원 접경지역, 핵심 체험은 유료(성인 1만5천→2만5천원 인상안 검토 중, 미확정)·주말 혼잡. 전국 인지도는 매우 높음.\n[영향성 8점] '관광객 수에서 지역 매출로' 개편과 외국인 유치가 지역경제 의제로 전국 뉴스에 반복 노출. 윈도우(~1/31) 안에 개막 후 23일 전 기간이 들어온다.\n[종합] 강점: 검증된 백만 명대 동원과 겨울 대표 영상 소재 / 약점·리스크: 화천군 개막 확정 공고 전이고 이상기온 결빙 부족 시 개막 연기 전례 → 연기 폭이 2주를 넘으면 윈도우 이탈, 체험료 인상 반발 / 편성 코멘트: 1/9 개막일 현장 생중계·스케치 1순위, 12월 말 결빙 상황 재확인.",
